const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Obtém a lista de clientes (do Webhook) e de investimentos (do HTTP Request / Code anterior)
const payload = $input.first().json;
const clientes = payload.body?.clientes || payload.clientes || [];
const investimentos = payload.investimentos || [];

// Função auxiliar para converter saldo formatado (ex: "R$ 12.500,00") em número
function parseSaldo(saldoStr) {
  if (typeof saldoStr === 'number') return saldoStr;
  if (!saldoStr) return 0;
  const limpo = String(saldoStr)
    .replace(/[^\d,-]/g, '')
    .replace('.', '')
    .replace(',', '.');
  return parseFloat(limpo) || 0;
}

// Função para escolher um item aleatório do array de mensagens
function pick(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

const resultados = clientes.map(c => {
  const saldoNum = parseSaldo(c.saldo);

  // Filtra opções compatíveis com o perfil do cliente
  const opcoesPerfil = investimentos.filter(inv => 
    String(inv.perfil).toLowerCase() === String(c.perfil).toLowerCase()
  );

  // Filtra opções em que o cliente atinge o saldo mínimo
  const opcoesElegiveis = opcoesPerfil.filter(inv => saldoNum >= (inv.minimo || 0));

  let escolhido = null;
  let motivo = "saldo_ok";

  if (opcoesElegiveis.length > 0) {
    // Pega o investimento elegível de maior valor mínimo
    escolhido = opcoesElegiveis.reduce((prev, curr) => (curr.minimo > prev.minimo) ? curr : prev);
  } else if (opcoesPerfil.length > 0) {
    // Se não tiver saldo para nenhum, pega a opção de menor valor do perfil para informar
    escolhido = opcoesPerfil.reduce((prev, curr) => (curr.minimo < prev.minimo) ? curr : prev);
    motivo = "saldo_insuficiente";
  }

  // Monta as variações de mensagens
  let mensagens = [];
  if (escolhido && motivo === "saldo_ok") {
    const minFormatado = chosenVal => Number(chosenVal).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const minText = minFormatado(escolhido.minimo);

    mensagens = [
      `Olá ${c.nome}! Pelo seu perfil (${c.perfil}), uma boa opção é **${escolhido.produto}** (mínimo ${minText}). Com seu saldo atual (${c.saldo}), você já consegue investir. Rentabilidade: ${escolhido.rentabilidade}.`,
      `Oi ${c.nome}! Recomendação para perfil ${c.perfil}: **${escolhido.produto}** (mínimo ${minText}). Seu saldo (${c.saldo}) já atende o mínimo. Rentabilidade: ${escolhido.rentabilidade}.`,
      `${c.nome}, indo direto ao ponto: para o perfil ${c.perfil}, **${escolhido.produto}** (mínimo ${minText}). Você tem ${c.saldo}, então dá pra aplicar. Rentabilidade: ${escolhido.rentabilidade}.`
    ];
  } else if (escolhido && motivo === "saldo_insuficiente") {
    mensagens = [
      `Olá ${c.nome}! Para o seu perfil (${c.perfil}), a principal opção é **${escolhido.produto}**, mas exige mínimo de R$ ${escolhido.minimo}. Seu saldo atual é ${c.saldo}.`,
      `Oi ${c.nome}! No perfil ${c.perfil}, recomendamos **${escolhido.produto}**. Você precisa de R$ ${escolhido.minimo} para começar (saldo atual: ${c.saldo}).`
    ];
  } else {
    mensagens = [
      `Olá ${c.nome}! Não encontramos investimentos disponíveis para o perfil ${c.perfil} no momento.`
    ];
  }

  return {
    nome: c.nome,
    email: c.email,
    perfil: c.perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo: motivo,
    mensagens: mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

