// Recebe todos os itens gerados pelo nó de IA
const items = $input.all();

return items.map((item, index) => {
  // 1. Acede aos dados correspondentes ao cliente do mesmo índice (item 0, 1, 2...)
  const j = $('Preparar Dados para IA').all()[index].json;

  // 2. Tenta obter o texto gerado pela IA cobrindo as estruturas comuns do n8n
  let rawText = "";
  if (typeof item.json.text === 'string') {
    rawText = item.json.text;
  } else if (item.json.message && item.json.message.content) {
    rawText = item.json.message.content;
  } else if (item.json.content && Array.isArray(item.json.content) && item.json.content[0]?.text) {
    rawText = item.json.content[0].text;
  } else if (item.json.response?.text) {
    rawText = item.json.response.text;
  }

  let parsed = {};

  // 3. Tenta extrair e converter o JSON gerado pela IA
  try {
    const cleanedText = rawText
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();
    parsed = JSON.parse(cleanedText);
  } catch (e) {
    // Fallback caso a IA devolva texto puro em vez de JSON
    parsed = {
      subject: `Recomendação de Investimento para ${j.nome || ''}`,
      text_body: rawText,
      html_body: `<p>${rawText.replace(/\n/g, '<br>')}</p>`
    };
  }

  // 4. Garante que os campos não vêm vazios se a IA mudar o nome da chave
  const to = j.email_to || j.email || "";
  const subject = parsed.subject || `Recomendação de Investimento para ${j.nome || ''}`;
  const text_body = parsed.text_body || parsed.text || "";

  // Se html_body vier vazio ou em branco, gera o HTML a partir do text_body ou do texto bruto
  let html_body = parsed.html_body || parsed.html || "";
  if (!html_body || html_body.trim() === "<p></p>" || html_body.trim() === "") {
    const baseContent = text_body || rawText;
    html_body = `<p>${baseContent.replace(/\n/g, '<br>')}</p>`;
  }

  return {
    json: {
      ok: true,
      to,
      subject,
      text_body,
      html_body,
      meta: {
        nome: j.nome,
        perfil: j.perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo
      }
    }
  };
});

// Filtra e organiza os clientes que não tinham um e-mail válido
const items = $input.all();

return items.map(item => {
  const meta = item.json.meta || {};

  return {
    json: {
      status: "FALHA_NO_ENVIO",
      motivo: "E-mail ausente ou inválido",
      cliente: meta.nome || "Não informado",
      email_tentado: item.json.to || "Vazio",
      data_tentativa: new Date().toISOString()
    }
  };
});
